import{_ as i,c as t,o,ao as n}from"./chunks/framework.DAsozCiY.js";const p=JSON.parse('{"title":"Vilinko Studio Minor Protection Terms","description":"","frontmatter":{},"headers":[],"relativePath":"en/agreement/protect_child.md","filePath":"en/agreement/protect_child.md"}'),r={name:"en/agreement/protect_child.md"};function a(s,e,l,c,u,d){return o(),t("div",null,e[0]||(e[0]=[n('<h1 id="vilinko-studio-minor-protection-terms" tabindex="-1">Vilinko Studio Minor Protection Terms <a class="header-anchor" href="#vilinko-studio-minor-protection-terms" aria-label="Permalink to &quot;Vilinko Studio Minor Protection Terms&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Version</p><p>Initial release date: August 6, 2025</p><p>Last updated date: August 6, 2025</p></div><p>In case of any conflict, the <a href="/agreement/protect_child.html"><strong>Simplified Chinese version</strong></a> shall prevail.</p><h2 id="_1-scope-of-application-and-definitions" tabindex="-1">1. Scope of Application and Definitions <a class="header-anchor" href="#_1-scope-of-application-and-definitions" aria-label="Permalink to &quot;1. Scope of Application and Definitions&quot;">​</a></h2><ul><li>These terms apply to all minor users (natural persons under the age of 18) who use the internet information technology tools and related services provided by Vilinko Studio (hereinafter referred to as &quot;we&quot;).</li><li>The services we provide include but are not limited to user login systems, forum services, personalized customization functions, computer desktop beautification tools, file interpreters, as well as related websites, clients, open-source projects, etc.</li><li>These terms are supplementary to the &quot;Vilinko Studio Software Service Agreement&quot; and the <a href="./privacy.html">Privacy Policy</a>, and have the same legal effect as the above agreements. If there is any inconsistency between these terms and other agreements, these terms shall prevail.</li></ul><h2 id="_2-guardian-s-responsibilities-and-consent" tabindex="-1">2. Guardian&#39;s Responsibilities and Consent <a class="header-anchor" href="#_2-guardian-s-responsibilities-and-consent" aria-label="Permalink to &quot;2. Guardian&#39;s Responsibilities and Consent&quot;">​</a></h2><ul><li>Minors must obtain the explicit consent of their legal guardians (hereinafter referred to as &quot;guardians&quot;) before using our services. Guardians should carefully read and understand these terms and related agreement contents.</li><li>Guardians are responsible for supervising minors&#39; use of the services and guiding minors to use various functions correctly and safely, including but not limited to: <ul><li>Managing minors&#39; account information to prevent account leakage or abuse</li><li>Controlling minors&#39; behavior of posting content on the forum to avoid inappropriate remarks</li><li>Restricting the time minors use the services to prevent excessive addiction</li><li>Reviewing the content uploaded by minors to the personalized customization function</li></ul></li></ul><h2 id="_3-protection-of-minors-information" tabindex="-1">3. Protection of Minors&#39; Information <a class="header-anchor" href="#_3-protection-of-minors-information" aria-label="Permalink to &quot;3. Protection of Minors&#39; Information&quot;">​</a></h2><ul><li>We only collect minors&#39; personal information within the scope permitted by laws and regulations and necessary for providing services, and must obtain the guardian&#39;s consent.</li><li>The collected minors&#39; information includes but is not limited to: <ul><li>Account registration information (to be completed with the assistance of guardians)</li><li>Service usage records (used for service optimization and security assurance)</li><li>Other information explicitly agreed to be provided by guardians</li></ul></li><li>We take additional security protection measures for minors&#39; information, including: <ul><li>Encrypted storage and transmission of data</li><li>Restricting access permissions to minors&#39; information</li><li>Regular security audits and risk assessments</li></ul></li><li>Without the explicit consent of the guardian, we will not: <ul><li>Disclose minors&#39; personal information to any third party</li><li>Use minors&#39; information for purposes other than service provision</li><li>Push commercial advertisements or marketing information to minors</li></ul></li></ul><h2 id="_4-service-content-and-usage-restrictions" tabindex="-1">4. Service Content and Usage Restrictions <a class="header-anchor" href="#_4-service-content-and-usage-restrictions" aria-label="Permalink to &quot;4. Service Content and Usage Restrictions&quot;">​</a></h2><ul><li>We conduct strict reviews of service content to ensure that it does not contain information harmful to minors&#39; physical and mental health, including but not limited to violence, pornography, gambling, drugs, etc.</li><li>The following restrictions are set for minors&#39; use of services: <ul><li>Forum services: Content posted by minors will undergo additional review, and posting illegal, irregular or inappropriate content is prohibited</li><li>Personalized customization function: Restrict the sharing scope of content involving minors&#39; portraits</li><li>Open-source project participation: When minors participate in GitHub open-source project contributions, identity verification must be completed with the assistance of guardians</li><li>Time management: Provide a usage duration reminder function, and guardians can set a daily usage limit</li></ul></li></ul><h2 id="_5-special-protection-for-intellectual-property-rights-in-open-source-projects" tabindex="-1">5. Special Protection for Intellectual Property Rights in Open-Source Projects <a class="header-anchor" href="#_5-special-protection-for-intellectual-property-rights-in-open-source-projects" aria-label="Permalink to &quot;5. Special Protection for Intellectual Property Rights in Open-Source Projects&quot;">​</a></h2><ul><li>For parts of the content open-sourced on GitHub, when minors participate in contributions (including code submission, issue feedback, etc.), guardians must confirm the legality of their contribution behavior and content.</li><li>The intellectual property rights of codes, documents and other contents contributed by minors in open-source projects belong to the minors, and guardians shall exercise relevant rights on their behalf.</li><li>We respect and protect the intellectual property rights of minors in open-source projects. Any organization or individual using such content must comply with relevant open-source agreements and laws and regulations, and shall not infringe upon the legitimate rights and interests of minors.</li><li>If it is found that the intellectual property rights of minors have been infringed in the open-source community, we will assist guardians in taking rights protection measures, including but not limited to issuing infringement notices and assisting in evidence collection.</li></ul><h2 id="_6-guardian-s-rights" tabindex="-1">6. Guardian&#39;s Rights <a class="header-anchor" href="#_6-guardian-s-rights" aria-label="Permalink to &quot;6. Guardian&#39;s Rights&quot;">​</a></h2><ul><li>Guardians have the right to consult, correct and delete the personal information and content generated by minors in the process of using the services.</li><li>Guardians have the right to request us to restrict or stop providing part or all of the services to minors.</li><li>Guardians have the right to cancel minors&#39; accounts. After account cancellation, we will handle relevant information in accordance with the provisions of the <a href="./privacy.html">Privacy Policy</a>.</li><li>Guardians can contact our customer service at any time for communication and handling if they have any questions or objections to minors&#39; use of the services.</li></ul><h2 id="_7-dispute-resolution-and-legal-application" tabindex="-1">7. Dispute Resolution and Legal Application <a class="header-anchor" href="#_7-dispute-resolution-and-legal-application" aria-label="Permalink to &quot;7. Dispute Resolution and Legal Application&quot;">​</a></h2><ul><li>Any dispute arising from these terms shall first be resolved through friendly negotiation between the parties; if the negotiation fails, either party has the right to file a lawsuit with the people&#39;s court with jurisdiction at the location of Vilinko Studio.</li><li>The formation, validity, interpretation, performance and dispute resolution of these terms shall be governed by the laws of the People&#39;s Republic of China.</li></ul><h2 id="_8-other-terms" tabindex="-1">8. Other Terms <a class="header-anchor" href="#_8-other-terms" aria-label="Permalink to &quot;8. Other Terms&quot;">​</a></h2><ul><li>We will revise these terms according to the update of laws and regulations and the development of services. The revised terms will be announced on official channels and notified to guardians through appropriate means.</li><li>If you have any questions about these terms, you can contact us via <a href="mailto:privacy@vilinko.com" target="_blank" rel="noreferrer">privacy@vilinko.com</a>.</li></ul>',19)]))}const m=i(r,[["render",a]]);export{p as __pageData,m as default};
